  }
}

@keyframes press-marquee {
  from { transform: translateX(0); }
  to   { transform: translateX(-50%); }
}
.press-marquee-track {
  animation: press-marquee 38s linear infinite;
  will-change: transform;
}
.press-marquee-mask:hover .press-marquee-track { animation-play-state: paused; }
@media (prefers-reduced-motion: reduce) { .press-marquee-track { animation: none; } }

@keyframes wheel-breathe-cover {
  0%, 100% { transform: scale(1); }
  50%      { transform: scale(1.012); }
}
.wheel-breathe { animation: wheel-breathe-cover 7s ease-in-out infinite; }
@media (prefers-reduced-motion: reduce) { .wheel-breathe { animation: none; } }

/* Breathing loop — a whisper of scale so the composition looks
   alive without looking restless. Rotation is now JS-driven
